 const [cat,setCat]=useState({name:'',emoji:'🎁',description:'',image:''}); const [product,setProduct]=useState(emptyProduct); const [editingCategory,setEditingCategory]=useState(null); const [editingProduct,setEditingProduct]=useState(null); const [subcategoryDrafts,setSubcategoryDrafts]=useState({}); const [subcategoryUploading,setSubcategoryUploading]=useState({}); const [categoryImageUploading,setCategoryImageUploading]=useState(false); const [imageUploading,setImageUploading]=useState(false); const [imageUploadName,setImageUploadName]=useState(''); const [imagePreview,setImagePreview]=useState(''); React.useEffect(()=>()=>{if(imagePreview&&imagePreview.startsWith('blob:'))URL.revokeObjectURL(imagePreview);},[imagePreview]); const selectedProductCategory=categories.find(c=>c.id===(product.category||categories[0]?.id));
