 const uploadProductImage=async(file)=>{
  if(!file)return;
  if(!file.type.startsWith('image/')){notify('Choose an image file','error');return;}
  if(file.size>5*1024*1024){notify('Please choose an image smaller than 5 MB','error');return;}
  const publicKey=import.meta.env.VITE_IMAGEKIT_PUBLIC_KEY;
  if(!publicKey){notify('Image uploads are not configured yet. Add the ImageKit public key and deploy the upload function.','error');return;}
  // Show the chosen file immediately; Android/iOS pickers can take a moment to upload.
  setImagePreview(old=>{if(old&&old.startsWith('blob:'))URL.revokeObjectURL(old);return URL.createObjectURL(file);});
  setProduct(old=>({...old,image:''}));
  setImageUploading(true);setImageUploadName(file.name);
  try{
   const signedInUser=auth?.currentUser;
   if(!signedInUser)throw new Error('Please sign in to the store admin before uploading a photo.');
   const idToken=await signedInUser.getIdToken();
   const authResponse=await fetch('/.netlify/functions/imagekit-auth',{headers:{Authorization:`Bearer ${idToken}`}});
   const authPayload=await authResponse.json().catch(()=>({}));
   if(!authResponse.ok){
    if(authResponse.status===404)throw new Error('The secure image-upload function was not found. Stop the server and restart with `netlify dev` (not `npm run dev`).');
    throw new Error(authPayload.error||`Secure image upload could not start (HTTP ${authResponse.status}). Check the Netlify function and local environment variables.`);
   }
   if(!authPayload.signature||!authPayload.token||!authPayload.expire)throw new Error('The upload service returned incomplete signing data. Check the ImageKit function logs and server-side environment variables.');
   const data=new FormData();
   data.append('file',file);data.append('fileName',file.name.replace(/[^a-zA-Z0-9._-]/g,'-'));
   data.append('publicKey',publicKey);data.append('signature',authPayload.signature);data.append('token',authPayload.token);data.append('expire',String(authPayload.expire));
   data.append('folder','/god-first-gift-shop/products');data.append('useUniqueFileName','true');data.append('responseFields','url,name,fileId,size,filePath');
   const uploadResponse=await fetch('https://upload.imagekit.io/api/v1/files/upload',{method:'POST',body:data});
   const uploaded=await uploadResponse.json().catch(()=>({}));
   if(!uploadResponse.ok){
    const reason=uploaded.message||uploaded.help||uploaded.error||`HTTP ${uploadResponse.status}`;
    throw new Error(`ImageKit upload failed: ${reason}. Check that the public and private keys belong to the same ImageKit account.`);
   }
   if(!uploaded.url)throw new Error('ImageKit accepted the request but returned no image URL. Please try again.');
   setProduct(old=>({...old,image:uploaded.url||old.image}));
   setImagePreview(uploaded.url||'');
   notify('Product photo uploaded successfully');
  }catch(error){notify(`${error.message||'Image upload failed. Please try again.'} The local preview is temporary; the photo must finish uploading before you publish.`, 'error');}
  finally{setImageUploading(false);}
 };
